405|   /**
406|    * Report for sessions dated from..to inclusive. Single pass over bookings
407|    * (grouped by session), so cost is O(sessions + bookings).
408|    */
409|   getWeeklyReport(from: string, to: string): WeeklyReport {
410|     const validDate = (d: string): boolean =>
411|       DATE_RE.test(d) && !Number.isNaN(Date.parse(`${d}T00:00:00Z`)) &&
412|       new Date(`${d}T00:00:00Z`).toISOString().slice(0, 10) === d;
413|     if (typeof from !== "string" || typeof to !== "string" || !validDate(from) || !validDate(to)) {
414|       throw new DomainError("validation", "from and to must be valid YYYY-MM-DD dates");
415|     }
416|     if (to < from) throw new DomainError("validation", "to must not be before from");
417| 
418|     const ratio = (n: number, d: number): number => (d > 0 ? Math.round((n / d) * 10000) / 10000 : 0);
419|     const grouped = this.bookings.groupBySession();
420|     const totalsBySize: Record<string, number> = {};
421|     const totals: WeeklyReport["totals"] = {
422|       sessions: 0,
423|       ticketsSold: 0,
424|       membersAdmitted: 0,
425|       occupancy: 0,
426|       hireIncomeCentsBySize: totalsBySize,
427|       hireIncomeCents: 0,
428|       refundedCents: 0,
429|       sessionsHeld: 0,
430|       sessionsCancelled: 0,
431|     };
432|     let capacityTotal = 0;
433|     const rows: SessionReportRow[] = [];
434|     for (const s of this.sessions.listBetween(from, to)) {
435|       let ticketsSold = 0;
436|       let membersAdmitted = 0;
437|       let refundedCents = 0;
438|       const bySize: Record<string, number> = {};
439|       for (const b of grouped.get(s.id) ?? []) {
440|         if (b.status === "refunded") {
441|           refundedCents += b.amountCents;
442|         } else if (b.status === "paid") {
443|           if (b.membershipNumber !== undefined) membersAdmitted += b.tickets;
444|           else ticketsSold += b.tickets;
445|           for (const [size, qty] of Object.entries(b.hire)) {
446|             bySize[size] = (bySize[size] ?? 0) + qty * s.hirePriceCents;
447|           }
448|         }
449|       }
450|       const hireIncomeCents = Object.values(bySize).reduce((n, v) => n + v, 0);
451|       rows.push({
452|         sessionId: s.id,
453|         date: s.date,
454|         start: s.start,
455|         end: s.end,
456|         status: s.status,
457|         capacity: s.capacity,
458|         ticketsSold,
459|         membersAdmitted,
460|         occupancy: ratio(ticketsSold + membersAdmitted, s.capacity),
461|         hireIncomeCentsBySize: bySize,
462|         hireIncomeCents,
463|         refundedCents,
464|       });
465|       totals.sessions++;
466|       totals.ticketsSold += ticketsSold;
467|       totals.membersAdmitted += membersAdmitted;
468|       totals.hireIncomeCents += hireIncomeCents;
469|       totals.refundedCents += refundedCents;
470|       for (const [size, v] of Object.entries(bySize)) totalsBySize[size] = (totalsBySize[size] ?? 0) + v;
471|       capacityTotal += s.capacity;
472|       if (s.status === "held") totals.sessionsHeld++;
473|       if (s.status === "cancelled") totals.sessionsCancelled++;
474|     }
475|     totals.occupancy = ratio(totals.ticketsSold + totals.membersAdmitted, capacityTotal);
476|     return { from, to, sessions: rows, totals };
477|   }
