488|   async purchase(sessionId: string, input: PurchaseInput): Promise<Booking> {
489|     this.expireOverdue();
490|     const session = this.getSession(sessionId);
491|     if (session.status === "held") throw new DomainError("conflict", "ticket sales for this session are on hold");
492|     if (session.status === "cancelled") throw new DomainError("conflict", "this session is cancelled");
493| 
494|     if (!input.skaterName || !input.email) {
495|       throw new DomainError("validation", "skaterName and email are required");
496|     }
497|     if (!isPosInt(input.tickets)) throw new DomainError("validation", "tickets must be a positive integer");
498|     const hire = input.hire ?? {};
499|     let hireTotal = 0;
500|     for (const [size, qty] of Object.entries(hire)) {
501|       if (!isPosInt(qty)) throw new DomainError("validation", `hire quantity for size ${size} must be a positive integer`);
502|       hireTotal += qty;
503|     }
504|     if (hireTotal > input.tickets) {
505|       throw new DomainError("validation", "cannot hire more skates than tickets");
506|     }
507| 
508|     const membershipNumber = input.membershipNumber;
509|     if (membershipNumber !== undefined) {
510|       if (!this.members.get(membershipNumber)) throw new DomainError("not_found", "membership not found");
511|       const month = session.date.slice(0, 7);
512|       if (this.freeEntriesUsed(membershipNumber, month) + input.tickets > FREE_ENTRIES_PER_MONTH) {
513|         throw new DomainError("conflict", `members get ${FREE_ENTRIES_PER_MONTH} free entries a month`);
514|       }
515|     }
516| 
517|     // Check and reserve synchronously so concurrent requests cannot oversell.
518|     const used = this.usage(sessionId);
519|     if (used.tickets + input.tickets > this.effectiveCapacity(session)) {
520|       throw new DomainError("conflict", "not enough tickets left for this session");
521|     }
522|     for (const [size, qty] of Object.entries(hire)) {
523|       if ((used.hire[size] ?? 0) + qty > this.stock.get(size)) {
524|         throw new DomainError("conflict", `not enough hire skates left in size ${size}`);
525|       }
526|     }
527| 
528|     const createdAt = this.now();
529|     const booking = this.bookings.create({
530|       sessionId,
531|       skaterName: input.skaterName,
532|       email: input.email,
533|       phone: typeof input.phone === "string" && input.phone ? input.phone : undefined,
534|       tickets: input.tickets,
535|       hire: { ...hire },
536|       amountCents:
537|         (membershipNumber !== undefined ? 0 : input.tickets * session.priceCents) +
538|         hireTotal * session.hirePriceCents,
539|       membershipNumber,
540|       status: "pending",
541|       createdAt,
542|       expiresAt: createdAt + PAYMENT_WINDOW_MS,
543|     });
544| 
545|     if (booking.amountCents === 0) {
546|       booking.status = "paid"; // nothing to pay: no checkout needed
547|       this.bookings.update(booking);
548|       return booking;
549|     }
550| 
551|     try {
552|       const checkout = await this.puckPay.createCheckout({
553|         reference: booking.id,
554|         amountCents: booking.amountCents,
555|         currency: "USD",
556|         description: `Skating ${session.date} ${session.start}-${session.end}`,
557|         callbackUrl: this.callbackUrl,
558|       });
559|       booking.checkoutUrl = checkout.checkoutUrl;
560|       booking.paymentId = checkout.paymentId;
561|       this.bookings.update(booking);
562|     } catch (err) {
563|       booking.status = "failed";
564|       this.bookings.update(booking);
565|       throw new DomainError("upstream", `could not create checkout: ${(err as Error).message}`);
566|     }
567|     return booking;
568|   }
