570|   /** Handles PuckPay's webhook. Idempotent for already-settled bookings. */
571|   async handlePaymentResult(result: PaymentResult): Promise<Booking> {
572|     this.expireOverdue();
573|     const booking = this.bookings.get(result.bookingId);
574|     if (!booking) throw new DomainError("not_found", "booking not found");
575|     if (booking.status === "cancelled" && result.status === "paid") {
576|       // Paid after its session was cancelled: give the money back.
577|       booking.paymentId = result.paymentId ?? booking.paymentId;
578|       try {
579|         await this.puckPay.refund({
580|           reference: booking.id,
581|           paymentId: booking.paymentId,
582|           amountCents: booking.amountCents,
583|           currency: "USD",
584|         });
585|         booking.status = "refunded";
586|         this.bookings.update(booking);
587|       } catch (err) {
588|         throw new DomainError("upstream", `could not refund booking: ${(err as Error).message}`);
589|       }
590|       return booking;
591|     }
592|     if (result.status === "refunded") {
593|       // PuckPay confirmed a refund: record it on the ticket (frees its capacity).
594|       if (booking.status === "paid") {
595|         booking.status = "refunded";
596|         if (result.paymentId) booking.paymentId = result.paymentId;
597|         this.bookings.update(booking);
598|       }
599|       return booking;
600|     }
601|     if (booking.status !== "pending") return booking; // expired/settled: ignore
602|     booking.status = result.status;
603|     if (result.paymentId) booking.paymentId = result.paymentId;
604|     this.bookings.update(booking);
605|     return booking;
606|   }
