608|   /** Releases unpaid bookings whose 15-minute window has elapsed. */
609|   expireOverdue(): number {
610|     const now = this.now();
611|     let count = 0;
612|     for (const b of this.bookings.list()) {
613|       if (b.status === "pending" && b.expiresAt <= now) {
614|         b.status = "expired";
615|         this.bookings.update(b);
616|         count++;
617|       }
618|     }
619|     return count;
